export function buildAppraisalSchedule(startISO = null) {
  return buildScheduleFor(APPRAISAL_MODULES, startISO, APPRAISAL_META.cadenceDays);
}

export function appraisalProgressSummary(progress = {}) {
  return progressSummaryFor(APPRAISAL_MODULES, progress);
}

export function exportAppraisalCurriculumMarkdown(startISO = null) {
  return exportCurriculumMarkdownFor({
    meta: APPRAISAL_META,
    modules: buildAppraisalSchedule(startISO),
    sessionFlow: APPRAISAL_SESSION_FLOW,
  }, startISO);
}

/** Every Scripture reference this course cites, deduped — what the verse gate walks. */
export function appraisalRefs() {
  const seen = new Set();
  for (const m of APPRAISAL_MODULES) {
    for (const part of String((m.anchor && m.anchor.ref) || '').split(';')) {
      const ref = part.trim();
      if (ref) seen.add(ref);
    }
  }
  for (const part of String((APPRAISAL_META.wordFirst && APPRAISAL_META.wordFirst.ref) || '').split(';')) {
    const ref = part.trim();
    if (ref) seen.add(ref);
  }
  return [...seen];
}

